def tag(dom,text,opts=None):
    blob=(text+' '+' '.join(opts or [])).lower()
    for name,rx in R.get(dom,[]):
        if re.search(rx,text.lower()): return name
    for name,rx in R.get(dom,[]):
        if re.search(rx,blob): return name
    return 'Fundamentals'
